	(5048, 'Ida B. Wells-Barnett', 'Early pioneer of investigative journalism and civil rights icon. Posthumous winner in 2020 of a Pulitzer Prize special citation.', NULL),
	(5049, 'Wendy Lambert', NULL, NULL),
